func resolveBusinessPKForMaster(binding *masterBindingRuntime, colTypes map[string]string) string {
	if pk := resolveConflictTarget(binding, colTypes); pk != "" && pk != "_gpay_id" {
		return pk
	}
	if binding == nil || binding.TransformType == "flatten" || colTypes == nil {
		return ""
	}
	for _, cand := range []string{binding.SourcePK, "_id", "id", "_source_id"} {
		if cand != "" && cand != "_gpay_id" && ddlIdentRe.MatchString(cand) {
			if _, ok := colTypes[cand]; ok {
				return cand
			}
		}
	}
	return ""
}

